// Own: zzOWN.com - Own Fast. Work Faster.  | Ema: zzown.com@gmail.com
// Des: Tests opening far chats: scroll, search, ambiguity, strangers
// Flo: sim with 306 virtual chats and a 500-message chat > open/locate/scroll > assert page state
// I/O: sim page > pass or fail
// Run: zig build test
// ===================================================================
const std = @import("std"); const opn = @import("ru-chat-open.zig"); const scrl = @import("ru-page-scrl.zig"); const extr = @import("ru-page-extr.zig"); const rig = @import("te-rigz-main.zig"); const T = std.testing;
test "phone detection needs 8 or more digits only" { try T.expect(opn.isPhone("0900000001")); try T.expect(!opn.isPhone("090000")); try T.expect(!opn.isPhone("09000000x1")); try T.expect(!opn.isPhone("")); }
test "target parse: qualifiers, trim, no qualifier" { const one = opn.parseTarget(" Anna#group "); try T.expectEqualStrings("Anna", one.name); try T.expect(one.qual == .group); const two = opn.parseTarget("Anna #Person"); try T.expectEqualStrings("Anna", two.name); try T.expect(two.qual == .person); const three = opn.parseTarget("Team A"); try T.expect(three.qual == .any); try T.expectEqualStrings("Team A", three.name); const four = opn.parseTarget("C#1"); try T.expectEqualStrings("C#1", four.name); }
test "js builders carry the selectors json-escaped" { var aren = std.heap.ArenaAllocator.init(T.allocator); defer aren.deinit(); const js = try extr.msgJs(aren.allocator(), .{ .msg_sel = "a[b=\"c\"]", .dir_atr = "data-dir" }); try T.expect(std.mem.find(u8, js, "a[b=\\\"c\\\"]") != null); try T.expect(std.mem.find(u8, js, "getAttribute(\"data-dir\")") != null); const cj = try extr.chatJs(aren.allocator(), .{ .chat_sel = "li" }); try T.expect(std.mem.find(u8, cj, "querySelectorAll(\"li\")") != null); }
test "extractor reads messages with id, dir, kind, time and no selector is NoElem" { var buff: [160]u8 = undefined; var rg: rig.Rig = undefined; try rg.up(&buff); defer rg.down(); const ses = rg.ses(rig.cfgOf(), .read); _ = try rg.js("openChat(Z.chats[0]);'x'"); const ms = try extr.msgsDom(ses.aren, ses.conn, rig.SIM_EXT); try T.expectEqual(@as(usize, 2), ms.len); try T.expectEqualStrings("them", ms[0].dir); try T.expectEqualStrings("text", ms[0].kind); try T.expectEqualStrings("Hi son", ms[0].text); try T.expect(ms[0].id.len > 0 and ms[0].time.len > 0); try T.expectError(error.NoElem, extr.msgsDom(ses.aren, ses.conn, .{})); const rows = try extr.chatsDom(ses.aren, ses.conn, rig.SIM_EXT); try T.expect(rows.len >= 5); try T.expectEqualStrings("Mom", rows[0].name); try T.expect(rows[0].x > 0 and rows[0].y > 0); }
test "open a chat that is far down a virtual list by scrolling, case-insensitive" { var buff: [160]u8 = undefined; var rg: rig.Rig = undefined; try rg.up(&buff); defer rg.down(); var ses = rg.ses(rig.cfgOf(), .live); const got = try opn.openChat(&ses, "contact 250"); try T.expectEqualStrings("Contact 250", got.name); try T.expect(!got.stran); try T.expectEqualStrings("Contact 250", try rg.js("Z.cur")); }
test "search finds a stranger; live without force is NeedForce, force opens, phone number works" { var buff: [160]u8 = undefined; var rg: rig.Rig = undefined; try rg.up(&buff); defer rg.down(); var live = rg.ses(rig.cfgOf(), .live); try T.expectError(error.NeedForce, opn.openChat(&live, "Zed")); try T.expectEqualStrings("", try rg.js("Z.cur")); const pck = try opn.locate(&live, "Zed"); try T.expect(pck.stran and pck.srch); var frc = rg.ses(rig.cfgOf(), .force); const got = try opn.openChat(&frc, "0900000001"); try T.expectEqualStrings("Zed", got.name); try T.expect(got.stran); try T.expectEqualStrings("Zed", try rg.js("Z.cur")); try T.expectEqualStrings("", try rg.js("document.getElementById('q').value")); }
test "same name is Ambiguous until a qualifier is given; unknown is NoElem" { var buff: [160]u8 = undefined; var rg: rig.Rig = undefined; try rg.up(&buff); defer rg.down(); var ses = rg.ses(rig.cfgOf(), .live); try T.expectError(error.Ambiguous, opn.openChat(&ses, "Anna")); const grp = try opn.openChat(&ses, "Anna#group"); try T.expectEqualStrings("Anna", grp.name); try T.expectEqualStrings("1", try rg.js("Z.curSel.group+''")); _ = try opn.openChat(&ses, "Anna#person"); try T.expectEqualStrings("0", try rg.js("Z.curSel.group+''")); try T.expectError(error.NoElem, opn.openChat(&ses, "Nobody At All")); try T.expectError(error.BadJob, opn.openChat(&ses, "  ")); }
test "history load: wheel up grows the message list to the goal and stops at the cap" { var buff: [160]u8 = undefined; var rg: rig.Rig = undefined; try rg.up(&buff); defer rg.down(); var cfg = rig.cfgOf(); cfg.scrl_step_maxz = 6; var ses = rg.ses(cfg, .read); _ = try rg.js("openChat(Z.chats[12]);'x'"); try T.expectEqual(@as(i64, 30), try rg.num("document.querySelectorAll('#thread [role=article]').length")); const reached = try scrl.loadOlder(&ses, 100); try T.expect(reached >= 100); try T.expect(reached < 500); var cfg2 = rig.cfgOf(); cfg2.scrl_step_maxz = 1; var tiny = rg.ses(cfg2, .read); const small = try scrl.loadOlder(&tiny, 500); try T.expect(small < 200); var none = rg.ses(rig.cfgOf(), .read); none.reg.ext = .{}; try T.expectError(error.NoElem, scrl.loadOlder(&none, 10)); }
test "loose name match ignores case, spaces and no-break spaces, and needs 5+ characters" { try T.expect(opn.looseHit("Nhóm Doctorfarm", "Nhóm\u{a0}Doctorfarm")); try T.expect(opn.looseHit("Nhóm Doctorfarm", "doctor farm")); try T.expect(!opn.looseHit("Nhóm Doctorfarm", "farm")); try T.expect(!opn.looseHit("Mom", "Dad Dad")); }
